package genaiconv

import (
	"encoding/json"
	"fmt"
)

// InputMessages is the ordered list of messages sent to a generative AI model.
type InputMessages []ChatMessage

// ChatMessage is one message sent to the model.
type ChatMessage struct {
	Role  Role    `json:"role"`
	Parts []Part  `json:"parts"`
	Name  *string `json:"name,omitempty"`
}

// OutputMessages is the ordered list of messages generated by a model or agent.
type OutputMessages []OutputMessage

// OutputMessage is one response choice or candidate generated by a model or agent.
type OutputMessage struct {
	Role         Role         `json:"role"`
	Parts        []Part       `json:"parts"`
	Name         *string      `json:"name,omitempty"`
	FinishReason FinishReason `json:"finish_reason"`
}

// Role identifies the entity that created a message. Providers may use values
// beyond the standard roles.
type Role string

const (
	RoleSystem    Role = "system"
	RoleUser      Role = "user"
	RoleAssistant Role = "assistant"
	RoleTool      Role = "tool"
)

// FinishReason identifies why the model stopped generating a response.
// Providers may use values beyond the standard reasons.
type FinishReason string

const (
	FinishReasonStop          FinishReason = "stop"
	FinishReasonLength        FinishReason = "length"
	FinishReasonContentFilter FinishReason = "content_filter"
	FinishReasonToolCall      FinishReason = "tool_call"
	FinishReasonCompaction    FinishReason = "compaction"
	FinishReasonError         FinishReason = "error"
)

// PartType identifies a message part variant.
type PartType string

const (
	PartTypeText                   PartType = "text"
	PartTypeToolCall               PartType = "tool_call"
	PartTypeToolCallResponse       PartType = "tool_call_response"
	PartTypeServerToolCall         PartType = "server_tool_call"
	PartTypeServerToolCallResponse PartType = "server_tool_call_response"
	PartTypeBlob                   PartType = "blob"
	PartTypeFile                   PartType = "file"
	PartTypeURI                    PartType = "uri"
	PartTypeReasoning              PartType = "reasoning"
	PartTypeCompaction             PartType = "compaction"
)

// Modality is the general kind of non-text data in a message part. Providers
// may use values beyond the standard modalities.
type Modality string

const (
	ModalityImage    Modality = "image"
	ModalityVideo    Modality = "video"
	ModalityAudio    Modality = "audio"
	ModalityDocument Modality = "document"
)

// Part is one standard or provider-specific message part.
type Part interface {
	Kind() PartType
	isPart()
}

// TextPart contains text sent to or received from the model.
type TextPart struct {
	Type    PartType `json:"type"`
	Content string   `json:"content"`
}

func (p TextPart) Kind() PartType { return p.Type }
func (TextPart) isPart()          {}

// ToolCallRequestPart is a tool invocation requested by the model.
type ToolCallRequestPart struct {
	Type      PartType `json:"type"`
	ID        *string  `json:"id,omitempty"`
	Name      string   `json:"name"`
	Arguments any      `json:"arguments,omitempty"`
}

func (p ToolCallRequestPart) Kind() PartType { return p.Type }
func (ToolCallRequestPart) isPart()          {}

// ToolCallResponsePart is a tool result sent to the model.
type ToolCallResponsePart struct {
	Type     PartType `json:"type"`
	ID       *string  `json:"id,omitempty"`
	Response any      `json:"response"`
}

func (p ToolCallResponsePart) Kind() PartType { return p.Type }
func (ToolCallResponsePart) isPart()          {}

// ServerToolCallPart is a provider-executed tool invocation.
type ServerToolCallPart struct {
	Type           PartType              `json:"type"`
	ID             *string               `json:"id,omitempty"`
	Name           string                `json:"name"`
	ServerToolCall GenericServerToolCall `json:"server_tool_call"`
}

func (p ServerToolCallPart) Kind() PartType { return p.Type }
func (ServerToolCallPart) isPart()          {}

// ServerToolCallResponsePart is the result of a provider-executed tool.
type ServerToolCallResponsePart struct {
	Type                   PartType                      `json:"type"`
	ID                     *string                       `json:"id,omitempty"`
	ServerToolCallResponse GenericServerToolCallResponse `json:"server_tool_call_response"`
}

func (p ServerToolCallResponsePart) Kind() PartType { return p.Type }
func (ServerToolCallResponsePart) isPart()          {}

// BlobPart contains inline binary data encoded as base64 in JSON.
type BlobPart struct {
	Type     PartType `json:"type"`
	MIMEType *string  `json:"mime_type,omitempty"`
	Modality Modality `json:"modality"`
	Content  string   `json:"content"`
}

func (p BlobPart) Kind() PartType { return p.Type }
func (BlobPart) isPart()          {}

// FilePart references a file previously uploaded to the provider.
type FilePart struct {
	Type     PartType `json:"type"`
	MIMEType *string  `json:"mime_type,omitempty"`
	Modality Modality `json:"modality"`
	FileID   string   `json:"file_id"`
}

func (p FilePart) Kind() PartType { return p.Type }
func (FilePart) isPart()          {}

// URIPart references external data by URI.
type URIPart struct {
	Type     PartType `json:"type"`
	MIMEType *string  `json:"mime_type,omitempty"`
	Modality Modality `json:"modality"`
	URI      string   `json:"uri"`
}

func (p URIPart) Kind() PartType { return p.Type }
func (URIPart) isPart()          {}

// ReasoningPart contains reasoning or thinking content received from a model.
type ReasoningPart struct {
	Type    PartType `json:"type"`
	Content string   `json:"content"`
}

func (p ReasoningPart) Kind() PartType { return p.Type }
func (ReasoningPart) isPart()          {}

// CompactionPart contains compacted conversation state.
type CompactionPart struct {
	Type    PartType `json:"type"`
	ID      *string  `json:"id,omitempty"`
	Content *string  `json:"content,omitempty"`
}

func (p CompactionPart) Kind() PartType { return p.Type }
func (CompactionPart) isPart()          {}

// GenericPart preserves a provider-specific message part.
type GenericPart map[string]any

// Kind returns the provider-specific type discriminator.
func (p GenericPart) Kind() PartType {
	typeName, _ := p["type"].(string)
	return PartType(typeName)
}

func (GenericPart) isPart() {}

// GenericServerToolCall preserves provider-specific server tool call details.
type GenericServerToolCall map[string]any

// GenericServerToolCallResponse preserves provider-specific server tool result details.
type GenericServerToolCallResponse map[string]any

func (m *ChatMessage) UnmarshalJSON(data []byte) error {
	var raw struct {
		Role  Role              `json:"role"`
		Parts []json.RawMessage `json:"parts"`
		Name  *string           `json:"name,omitempty"`
	}
	if err := json.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("decode chat message: %w", err)
	}

	parts := make([]Part, len(raw.Parts))
	for i, partData := range raw.Parts {
		part, err := unmarshalPart(partData)
		if err != nil {
			return fmt.Errorf("decode chat message part %d: %w", i, err)
		}
		parts[i] = part
	}

	*m = ChatMessage{
		Role:  raw.Role,
		Parts: parts,
		Name:  raw.Name,
	}
	return nil
}

func (m *OutputMessage) UnmarshalJSON(data []byte) error {
	var raw struct {
		Role         Role              `json:"role"`
		Parts        []json.RawMessage `json:"parts"`
		Name         *string           `json:"name,omitempty"`
		FinishReason FinishReason      `json:"finish_reason"`
	}
	if err := json.Unmarshal(data, &raw); err != nil {
		return fmt.Errorf("decode output message: %w", err)
	}

	parts := make([]Part, len(raw.Parts))
	for i, partData := range raw.Parts {
		part, err := unmarshalPart(partData)
		if err != nil {
			return fmt.Errorf("decode output message part %d: %w", i, err)
		}
		parts[i] = part
	}

	*m = OutputMessage{
		Role:         raw.Role,
		Parts:        parts,
		Name:         raw.Name,
		FinishReason: raw.FinishReason,
	}
	return nil
}

func unmarshalPart(data []byte) (Part, error) {
	var discriminator struct {
		Type PartType `json:"type"`
	}
	if err := json.Unmarshal(data, &discriminator); err != nil {
		return nil, fmt.Errorf("decode part discriminator: %w", err)
	}

	var part Part
	switch discriminator.Type {
	case PartTypeText:
		part = new(TextPart)
	case PartTypeToolCall:
		part = new(ToolCallRequestPart)
	case PartTypeToolCallResponse:
		part = new(ToolCallResponsePart)
	case PartTypeServerToolCall:
		part = new(ServerToolCallPart)
	case PartTypeServerToolCallResponse:
		part = new(ServerToolCallResponsePart)
	case PartTypeBlob:
		part = new(BlobPart)
	case PartTypeFile:
		part = new(FilePart)
	case PartTypeURI:
		part = new(URIPart)
	case PartTypeReasoning:
		part = new(ReasoningPart)
	case PartTypeCompaction:
		part = new(CompactionPart)
	default:
		var generic GenericPart
		if err := json.Unmarshal(data, &generic); err != nil {
			return nil, fmt.Errorf("decode %q part: %w", discriminator.Type, err)
		}
		return generic, nil
	}

	if err := json.Unmarshal(data, part); err != nil {
		return nil, fmt.Errorf("decode %q part: %w", discriminator.Type, err)
	}
	return part, nil
}
